.e-ripple,
.e-ripple-style {
  overflow: hidden;
  position: relative;
  transform: translate3d(0, 0, 0);
}

.e-ripple-element,
.e-ripple-style::after {
  background: linear-gradient(90deg, rgba(28, 27, 31, 0.08) 0%, rgba(28, 27, 31, 0.1) 5%, rgba(28, 27, 31, 0.1) 50%, rgba(28, 27, 31, 0.1) 50%, rgba(28, 27, 31, 0.1) 95%, rgba(28, 27, 31, 0.08) 100%);
  border-radius: 0;
  overflow: hidden;
  pointer-events: none;
  position: absolute;
  transform: scale(0);
  transition: opacity 0.3s transform 50ms cubic-bezier(0.2, 0, 0, 1);
}

.e-ripple-style::after {
  background: rgba(28, 27, 31, 0.12);
  content: "";
  display: block;
  height: 50%;
  left: 25%;
  opacity: 0;
  top: 25%;
  transform: scale(3);
  transition: transform 0.3s, opacity 0.3s;
  width: 50%;
}
.e-ripple-style:active::after {
  opacity: 1;
  transform: scale(0);
  transition: 0s;
}

