}
.e-bigger.e-headless-editor code:not(pre *),
.e-bigger .e-headless-editor code:not(pre *) {
  font-size: inherit;
  line-height: inherit;
  padding: 1px 4px;
}
.e-bigger.e-headless-editor,
.e-bigger .e-headless-editor {
  /* Code Block Styles */
}
.e-bigger.e-headless-editor .e-code-block,
.e-bigger .e-headless-editor .e-code-block {
  margin: 8px 0;
}
.e-bigger.e-headless-editor .e-code-block pre,
.e-bigger .e-headless-editor .e-code-block pre {
  margin: 0;
  padding-left: 24px;
  overflow-x: auto;
  font-size: 16px;
  line-height: 24px;
}
.e-bigger.e-headless-editor,
.e-bigger .e-headless-editor {
  /* ======== Divider Blocks Level styles ======== */
}
.e-bigger.e-headless-editor hr[contenteditable=false],
.e-bigger .e-headless-editor hr[contenteditable=false] {
  margin-block: 14px;
}
.e-bigger.e-headless-editor,
.e-bigger .e-headless-editor {
  /* ======== Table Block Styles ======== */
}
.e-bigger.e-headless-editor .tableWrapper table th,
.e-bigger .e-headless-editor .tableWrapper table th {
  height: 38px;
  padding: 9px;
  font-size: 14px;
  line-height: 20px;
}
.e-bigger.e-headless-editor .tableWrapper table td,
.e-bigger .e-headless-editor .tableWrapper table td {
  height: 48px;
  padding: 9px;
  font-size: 14px;
  line-height: 20px;
}
.e-bigger.e-headless-editor,
.e-bigger .e-headless-editor {
  /* ======== RTL Styles ======== */
}
.e-bigger.e-headless-editor.e-rtl blockquote,
.e-bigger .e-headless-editor.e-rtl blockquote {
  border-left-width: unset;
  border-right-width: 3px;
  padding: 0 8px 0 0;
}
.e-bigger.e-headless-editor.e-rtl,
.e-bigger .e-headless-editor.e-rtl {
  /* collapsible */
}
.e-bigger.e-headless-editor.e-rtl [data-type=collapsible] .e-collapsible-body-content,
.e-bigger .e-headless-editor.e-rtl [data-type=collapsible] .e-collapsible-body-content {
  padding-left: unset;
  padding-right: 28px;
}
.e-bigger.e-headless-editor.e-rtl,
.e-bigger .e-headless-editor.e-rtl {
  /* Task List */
}
.e-bigger.e-headless-editor.e-rtl ul[data-type=taskList] li > label,
.e-bigger .e-headless-editor.e-rtl ul[data-type=taskList] li > label {
  padding-right: unset;
  padding-left: 8px;
}